  ?z a brick:Zone ; rdfs:label ?zlabel .
  FILTER(?zlabel IN ("Perimeter_mid_ZN_3","DataCenter_top_ZN_6"))
  OPTIONAL { ?z ref:hasTimeseriesId ?ts }
}

SELECT ?z ?ts ?p WHERE {
  VALUES ?z {
    http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02
    http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09
  }
  OPTIONAL { ?z ref:hasTimeseriesId ?ts }
  OPTIONAL { ?z ?p ?o }
}

SELECT ?p ?ts WHERE {
  VALUES ?z {
    http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z02
    http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09
  }
  ?p ?pred ?z .
  FILTER(?pred != rdf:type)
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

SELECT ?p ?ts WHERE {
  { ?p ref:hasExternalReference ?z1 . ?z1 rdf:type brick:Zone }
  UNION
  { ?p ?r ?z . FILTER(?r != rdf:type) }
  FILTER(?p a brick:Point)
} LIMIT 200

